async function publish(){if(!await ownerAccess.verify())return false;if(editorMode==='combat'&&page==='editor')await captureCombat();const errors=projectProblems(draft);for(const g of draft.guests)errors.push(...validate(draft.combat,{monsterID:g.id}).errors);if(errors.length){modal('<h2>저장 전에 확인해 주세요.</h2><p>'+errors.map(htmlEsc).join('<br>')+'</p><div class="actions">'+btn('errorOK','편집으로 돌아가기',true)+'</div>');el('errorOK').onclick=closeModal;return false;}const next=copy(draft);next.version=(published.version||1)+1;next.updatedAt=new Date().toISOString();try{localStorage.setItem(STORE,JSON.stringify(next));}catch{toast('브라우저 저장 공간이 부족합니다. 프로젝트 파일 저장으로 보관해 주세요.');return false;}published=next;draft.version=next.version;draft.updatedAt=next.updatedAt;dirty=false;el('dirtyFlag').textContent='저장됨 · v'+next.version;el('saveState').textContent='내 작업본 v'+next.version;el('projectVersion').textContent='내 브라우저의 작업본 · v'+next.version;toast('이 브라우저에 저장했어요. 개발실의 ‘내 작업본으로 시험 플레이’에서 확인하세요.');return true;}
async function downloadProject(){if(!await ownerAccess.verify())return;const blob=new Blob([JSON.stringify(draft,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='야차차_통합프로젝트_v'+draft.version+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('미용·야차·대사를 함께 담은 프로젝트를 저장했습니다.');}
function captureCombat(){if(!combatFrame||editorMode!=='combat'||combatFrame!==el('combatEditor'))return Promise.resolve();return new Promise((resolve,reject)=>{const id=token(),timer=setTimeout(()=>{snapshotResolvers.delete(id);toast('전투 실험실을 불러오는 중입니다. 잠시 후 다시 눌러 주세요.');reject(Error('전투 실험실 응답 대기 시간 초과'));},12000);snapshotResolvers.set(id,{resolve:()=>{clearTimeout(timer);resolve();},reject});combatFrame.contentWindow.postMessage({type:'snapshot',token:combatToken,requestID:id},'*');});}
