function battleEnd(outcome,stats){if(!story||story.outcome)return;story.outcome=outcome;story.stats=stats;gameAudio.music('salon');document.body.classList.remove('inBattle');el('storyBattle').srcdoc='';combatFrame=null;el('battleHost').hidden=true;sendSalon('salon-return');updateStoryHud(outcome==='victory'?'야차 승리 · 미용실로':'야차 패배');if(outcome==='defeat'){modal('<h2>잠깐 숨을 고를까요?</h2><p>다시 도전하면 현재 손님의 야차를 처음부터 시작합니다. 앞서 마친 미용 결과는 유지됩니다.</p><div class="actions">'+btn('lossContinue','패배 결과로 계속')+btn('retryBattle','다시 도전',true)+'</div>');el('retryBattle').onclick=()=>{closeModal();story.outcome=null;startBattle();};el('lossContinue').onclick=()=>{closeModal();say('afterLoss',finishCustomer);};}else say('afterWin',()=>{if(story.guest.id===10002)soulTutorial();else finishCustomer();});}
function soulTutorial(){story.soulUnlocked=true;modal(`<span class="eyebrow">MONSTER SOUL · FIRST LESSON</span><h2>잊고 있던 손끝의 감각</h2><p>취객의 가업은 몬스터의 소울에 남은 힘을 <b>장비와 기술</b>로 빚어내는 일입니다. 야차를 마치고 미용실로 돌아온 지금, 그 이야기가 시작됩니다.</p><div class="mutedbox">① 소울에 남은 특성을 살펴보기<br>② 장비 또는 기술로 다듬기<br>③ 다음 야차에 사용할 힘 고르기</div><p class="minor">이 빌드에서는 해금 연출과 안내까지 연결했습니다. 소울의 실제 제작·장착 시스템은 후속 구현 영역입니다.</p><div class="actions">${btn('soulDone','기억해 둘게요',true)}</div>`);el('soulDone').onclick=()=>{closeModal();finishCustomer();};}
function finishCustomer(){const g=story.guest;if(!story.resultRecorded){const base=g.beauty.enabled?g.beauty.basePay:0,pay=story.outcome==='defeat'&&story.lastScore<40?0:Math.round(base*(story.lastScore>=80?1+g.beauty.tipRate:1)),bonus=story.outcome==='victory'?300:0;story.money+=pay+bonus;story.records.push({day:story.day,id:g.id,name:g.name,score:g.beauty.enabled?Math.round(story.lastScore):null,outcome:story.outcome,pay,bonus,portrait:story.portrait||skin(g).full});story.resultRecorded=true;}updateStoryHud('손님 배웅');say('leave',()=>{if(g.id===10003&&story.outcome==='victory')departed();else sendSalon('depart',{portrait:story.portrait||skin(g).full});});}
