function openPhone(){if(!story)return;el('phoneButton').hidden=true;const zombie=story.records.find(r=>r.id===10001);modal('');el('modalCard').className='modalcard phoneModal';el('modalCard').innerHTML=`<div class="phoneTop"><b>monstagram</b><button id="phoneClose" aria-label="폰 닫기">×</button></div><div class="feed">${zombie?`<article class="post"><h3>● @zombie_jobseeker · 오늘</h3><img src="${zombie?.score>=40?ASSETS.monstagramSuccess:ASSETS.monstagramFailure}" class="storyPostImage" alt="${zombie?.score>=40?'미용 성공 · 회사 앞 좀비의 기념 사진':'미용 실패 · 미용실 앞 좀비의 사진'}"><p>${zombie?.score>=40?'내일 면접 준비 완료. 앞이 보이니 미래도 조금 보이는 것 같습니다... 으어어.':'면접 전날 머리에 큰 변화가 생겼습니다... 면접관이 저를 잊지는 못하겠군요. 으어어.'}<br><b>#다시_불_켜진_미용실 #야차차</b></p><small>♡ 좋아요 31개　☏ 댓글 3개</small></article>`:''}<article class="post"><h3>● @old_craft_hands · 방금</h3><img src="${ASSETS.drunkFull}" alt="취객"><p>오래된 친구의 가게에 다시 불이 켜졌다.<br>오늘은 술 대신, 먼지 쌓인 도구를 꺼내 본다.</p><small>♡ 좋아요 12개　@bone_afternoon: 내일 한번 들를게.</small></article></div><div class="phoneNav"><span>⌂</span><span>♡</span>${btn('nextDay','2일차 영업 시작 →')}</div>`;el('phoneClose').onclick=()=>{closeModal();el('phoneButton').hidden=false;};el('nextDay').onclick=()=>{closeModal();story.day=2;story.index=0;startCustomer();};}
function demoEnd(){modal(`<span class="eyebrow">END OF THE PLAYABLE BUILD</span><h2>불을 켜 두길 잘했네요.</h2><p>1일차 좀비와 취객, 2일차 샌즈까지 영업을 마쳤습니다.<br>개발실에서 설정을 바꾸고 또 다른 하루를 시험해 보세요.</p><div class="actions">${btn('endDev','개발실로')}${btn('endHome','메인 화면',true)}</div>`);el('endHome').onclick=homeNow;el('endDev').onclick=()=>{homeNow();showPage('dev');};}
addEventListener('message',e=>{const m=e.data;if(m?.source==='yachacha-salon'&&e.source===el('salon').contentWindow&&m.token===salonToken){if(m.type==='ready'){pendingSalon?.();pendingSalon=null;}if(m.type==='sound')gameAudio.effect(m.key);if(m.type==='cutscene-start'){updateStoryHud('뜻밖의 손님 · 등장 연출');el('storyHint').hidden=true;}if(m.type==='cutscene-end'){updateStoryHud('손님에게 말 걸기 · F');el('salon').focus();}if(m.type==='arrival')arrival();if(m.type==='dialogue-next')advanceTalk();if(m.type==='stage-request'&&story){const requestToken=salonToken;say(m.stage,result=>{if(requestToken!==salonToken)return;sendSalon('beauty-request-done',{requestId:m.requestId,detail:!!result?.detail});el('salon').focus();},!!m.detail);}if(m.type==='beauty-result')beautyResult(m.score,m.portrait);if(m.type==='departed')departed();if(m.type==='home')askExit();}
 if(m?.source==='yachacha-combat'&&e.source===combatFrame?.contentWindow&&m.token===combatToken){if(m.type==='owner-prompt')ownerAccess.login();if(m.type==='owner-check'){const frame=combatFrame,checkToken=combatToken;ownerAccess.verify().then(allowed=>{if(frame===combatFrame&&checkToken===combatToken)frame.contentWindow?.postMessage({type:'owner-result',token:checkToken,requestID:m.requestID,allowed},'*');});}if(m.type==='load-error'&&page==='story'){modal('<h2>야차 화면을 준비하지 못했어요</h2><p>미용 결과는 유지되어 있어요. 전투 화면을 다시 불러올 수 있습니다.</p><p>'+htmlEsc(m.message)+'</p><div class="actions">'+btn('retryBattleLoad','야차 다시 불러오기',true)+btn('exitBattleLoad','메인 화면')+'</div>');el('retryBattleLoad').onclick=()=>{closeModal();startBattle();};el('exitBattleLoad').onclick=homeNow;}if(m.type==='snapshot'){draft.combat=m.data;markDirty();snapshotResolvers.get(m.requestID)?.resolve();snapshotResolvers.delete(m.requestID);}if(m.type==='sound')gameAudio.effect(m.key);if(m.type==='battle-end')battleEnd(m.outcome,m.stats);}});
el('home').onclick=askExit;el('storyExit').onclick=askExit;el('play').onclick=()=>chooseStoryStart(false);el('playSaved').onclick=()=>chooseStoryStart(true);el('developer').onclick=()=>{showPage('dev');openUpdates();};el('showUpdates').onclick=()=>openUpdates(true);el('editorBack').onclick=async()=>{if(editorMode==='combat')await captureCombat();stopChildren();showPage('dev');};document.querySelectorAll('[data-editor]').forEach(b=>b.onclick=()=>openEditor(b.dataset.editor).catch(e=>toast(e.message)));el('publish').onclick=()=>publish().catch(e=>toast(e.message));el('editorSave').onclick=()=>publish().catch(e=>toast(e.message));el('exportProject').onclick=downloadProject;el('importProject').onclick=async()=>{if(await ownerAccess.verify())el('projectFile').click();};el('projectFile').onchange=async e=>{try{if(!await ownerAccess.verify())return;const f=e.target.files[0];if(!f)return;if(f.size>20e6)throw Error('프로젝트 파일이 너무 큽니다.');const next=JSON.parse(await f.text()),errors=projectProblems(next);if(errors.length)throw Error(errors[0]);draft=next;markDirty();toast('프로젝트를 불러왔어요. ‘내 브라우저에 저장’을 눌러 주세요.');}catch(err){toast(err.message);}e.target.value='';};el('talkNext').onclick=advanceTalk;el('beautyAsk').onclick=clarifyBeautyRequest;el('beautyAccept').onclick=advanceTalk;el('phoneButton').onclick=openPhone;el('soundToggle').onclick=soundToggle;el('help').onclick=()=>{modal('<h2>미용실에서의 하루</h2><p><b>이동</b> WASD · 손님 앞에서 F<br><b>대사</b> F 또는 Enter, 화면의 다음 버튼<br><b>가위</b> 누른 채 드래그하고 놓으면 잘림 · 세로 커트 가능<br><b>발모제</b> 머리카락·뼈를 더한 뒤 다시 손질하기<br><b>색·무늬</b> 만들어진 재료 위에 색칠 · 좀비·샌즈는 자유 체험<br><b>망치·정</b> 도구를 고른 뒤 얼굴 테두리를 클릭하거나 드래그해 깎기<br><b>스티커</b> 스티커 선택 → 얼굴 클릭. 붙인 장식 클릭으로 제거<br><b>야차</b> 방향키 이동 · F 패링/가드 · 빈틈에서 SPACE 연타</p><p>메인의 본편 플레이는 공개된 최신 설정으로 시작합니다. 개발실의 저장은 내 브라우저에만 적용됩니다. 다른 사람에게도 반영하려면 프로젝트 파일을 저장해서 사이트 배포 데이터에 반영해 주세요.</p><div class="actions">'+btn('helpOK','알겠어요',true)+'</div>');el('helpOK').onclick=closeModal;};document.querySelectorAll('[data-effect]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>applyEffect(b.dataset.effect);});el('effectClose').onclick=()=>el('effectPopup').hidden=true;
addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(talk&&['Enter','f','F',' '].includes(e.key)){e.preventDefault();if(document.activeElement?.id==='beautyAsk')clarifyBeautyRequest();else advanceTalk();}if(e.key==='Escape')el('effectPopup').hidden=true;});addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
