window.fullflow={get project(){return copy(draft);},get published(){return copy(published);},get story(){return story?{day:story.day,index:story.index,guest:story.guest?.id,money:story.money,records:copy(story.records),preview:story.preview}:null;},get page(){return page;}};
el('ownerLogin').onclick=()=>ownerAccess.login();el('ownerLogout').onclick=()=>ownerAccess.logout();await ownerAccess.restore();
await prepareSkins();background();el('projectVersion').textContent='내 브라우저의 작업본 · v'+published.version;requestAnimationFrame(animate);
